"use strict";
const $=id=>document.getElementById(id), T=AfterGridTheme, root=document.documentElement;
const system=matchMedia("(prefers-color-scheme: dark)");
let customPackages=[];
try{customPackages=T.loadPackages(localStorage.getItem("aftergrid-ui-themes-v1")||"[]");}catch{}
const themeList=()=>T.builtins.concat(customPackages.map(p=>p.theme));
const themeResolve=()=>T.resolve(prefs.theme,prefs.mode,system.matches,customPackages.map(p=>p.theme));
const esc=v=>String(v).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
function savePackages(next){localStorage.setItem("aftergrid-ui-themes-v1",JSON.stringify(next));customPackages=next;}
const defaultPrefs={theme:"overwatch",mode:"dark",density:"comfortable",motion:false,favorites:[]};
const appStates=Object.create(null);
let prefs={...defaultPrefs}, workspace="admin", page="overview", step=0, selected=new Set(), installed=new Set(["knowledge","maps","communications","supplies","homebox","notes"]), activity=["Example: Knowledge archive indexed","Example: Backup verification completed"];
try{const saved=JSON.parse(localStorage.getItem("aftergrid-ui-prototype-v1")||"null");if(saved&&typeof saved==="object"){prefs={theme:themeList().some(t=>t.id===saved.theme)?saved.theme:defaultPrefs.theme,mode:["light","dark","system"].includes(saved.mode)?saved.mode:defaultPrefs.mode,density:saved.density==="compact"?"compact":"comfortable",motion:saved.motion===true,favorites:Array.isArray(saved.favorites)?saved.favorites.filter(x=>typeof x==="string").slice(0,20):[]};}}catch{}
const paths={overview:"M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z",knowledge:"M3 4l9 3 9-3v15l-9 3-9-3z M12 7v15",maps:"M3 5l6-3 6 4 6-3v16l-6 3-6-4-6 3z M9 2v16 M15 6v16",communications:"M5 8h14v13H5z M9 8l7-6 M8 12h8 M8 16h8",supplies:"M3 6l9-4 9 4v12l-9 4-9-4z M3 6l9 5 9-5 M12 11v11",education:"M2 8l10-5 10 5-10 5z M5 10v7l7 4 7-4v-7",notes:"M5 3h14v18H5z M8 7h8 M8 11h8 M8 15h6",media:"M3 4h18v16H3z M10 8l6 4-6 4z",plans:"M6 4h12v17H6z M9 2h6v4H9z M9 10h6 M9 14h6",applications:"M4 4h16v16H4z M4 12h16 M12 4v16",content:"M12 3v13 M7 11l5 5 5-5 M4 17v4h16v-4",updates:"M20 8a8 8 0 1 0 0 8 M20 3v5h-5",backup:"M12 2l9 4v6c0 5-5 9-9 10-4-1-9-5-9-10V6z M8 12l3 3 5-6",appearance:"M12 3a9 9 0 1 0 0 18h2a2 2 0 0 0 0-4h-1a1 1 0 0 1 0-2h5a3 3 0 0 0 3-3 9 9 0 0 0-9-9z M7 8h.1 M12 6h.1 M17 8h.1",setup:"M4 5h16v14H4z M8 9h8 M8 13h8",activity:"M2 12h5l3-7 4 14 3-7h5"};
function icon(id){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'+(paths[id]||paths.overview)+'"/></svg>';}
const tools=[["knowledge","Knowledge library","Kiwix","Read offline guides and reference material."],["maps","Maps & navigation","MapLibre / Valhalla","Explore local maps and plan routes."],["communications","Communications","MeshMonitor","Mesh networks and manual device checks."],["supplies","Food & supplies","Grocy / Homebox","Track food, equipment and recipes."],["education","Education","Kolibri","Offline lessons and learning resources."],["notes","Notes & documents","DokuWiki","Shared documents and local references."],["media","Media library","Jellyfin","Access locally stored media."],["plans","Emergency plans","AfterGrid","Review shared PACE plans."]];
const catalogApps=tools.filter(t=>t[0]!=="plans").map(t=>t[0]==="supplies"?["supplies","Grocy","Grocy","Food stock, recipes and consumables."]:t).concat([["homebox","Homebox","Homebox","Equipment and storage locations."]]);
const categories={knowledge:"Knowledge",education:"Knowledge",maps:"Navigation",communications:"Communications",supplies:"Inventory",homebox:"Inventory",notes:"Documents",media:"Media"};
const resourceAvailable=id=>id==="plans"||installed.has(id)||id==="supplies"&&installed.has("homebox");
const adminNav=[["overview","Overview"],["applications","Applications"],["content","Content & maps"],["supplies","Households & inventory"],["updates","Updates"],["backup","Backup & recovery"],["activity","Activity"],["notifications","Notifications"],["setup","Setup wizard"],["marketplace","Marketplace (future)"],["appearance","Appearance"]];
const homeNav=()=>[["home","Home"],...tools.filter(t=>resourceAvailable(t[0])).map(t=>[t[0],t[1]]),["appearance","Appearance"]];
function persist(){try{localStorage.setItem("aftergrid-ui-prototype-v1",JSON.stringify(prefs));}catch{}}
function apply(){T.apply(root,themeResolve());root.dataset.density=prefs.density;root.dataset.motion=prefs.motion?"reduced":"normal";persist();}
document.querySelector(".skip").addEventListener("click",e=>{e.preventDefault();$("main").focus();});
function go(id){if(id==="home"){workspace="home";}if(id==="overview")workspace="admin";if(page===id&&location.hash==="#"+id){render();return;}location.hash=id;}
function readRoute(){const id=location.hash.slice(1);if(id==="main"&&$("page").children.length)return;if(id==="home")workspace="home";if(id==="overview"||id.startsWith("app-")||["applications","marketplace","setup","backup","updates","activity","notifications","content"].includes(id))workspace="admin";else if(["knowledge","maps","communications","education","notes","media","plans"].includes(id))workspace="home";const allowed=(workspace==="home"?homeNav():adminNav).some(n=>n[0]===id)||(workspace==="admin"&&id.startsWith("app-")&&catalogApps.some(t=>t[0]===id.slice(4)));page=allowed?id:workspace==="home"?"home":"overview";render();}
function nav(){const mobile=$("mobile-nav");mobile.hidden=workspace!=="home";mobile.innerHTML=[["home","Home"],["knowledge","Knowledge"],["maps","Maps"],["plans","Plans"],["appearance","Settings"]].filter(([id])=>id==="home"||id==="appearance"||resourceAvailable(id)).map(([id,label])=>'<a href="#'+id+'" '+(page===id?'aria-current="page"':'')+'>'+icon(id)+'<span>'+label+'</span></a>').join("");document.body.dataset.workspace=workspace;
updateNoticeCount();const items=workspace==="home"?homeNav():adminNav;$("workspace").value=workspace;
const link=([id,name])=>'<a class="nav-item" href="#'+id+'" '+((id===page||id==="applications"&&page.startsWith("app-"))?'aria-current="page"':'')+'>'+icon(id)+name+'</a>';
const groups=workspace==="admin"?[["Operations",["overview","applications","activity","notifications"]],["Resources",["content","supplies"]],["System",["updates","backup","setup","appearance","marketplace"]]]:[["Household",items.map(t=>t[0]).filter(id=>id!=="appearance")],["Preferences",["appearance"]]];
$("navigation").innerHTML=groups.map(([label,ids])=>'<div class="nav-group"><span class="nav-heading">'+label+'</span>'+ids.map(id=>items.find(t=>t[0]===id)).filter(Boolean).map(link).join("")+'</div>').join("");
$("breadcrumb").textContent=(workspace==="home"?"Household":"Administration")+" / "+(page.startsWith("app-")?"Application details":(items.find(n=>n[0]===page)||items[0])[1]);
}
function heading(title,description){return '<div class="page-heading"><div><div class="eyebrow">'+(workspace==="home"?"Household workspace":"Administration workspace")+'</div><h1>'+title+'</h1><p>'+description+'</p></div></div>';}
function tile(t,catalog=false){const [id,name,upstream,desc]=t;const available=catalog?installed.has(id):resourceAvailable(id);const favorite=prefs.favorites.includes(id);return '<article class="tile"><div class="tile-top"><div class="tile-icon">'+icon(id==="homebox"?"supplies":id)+'</div>'+(catalog?'<span class="status">'+(available?"Installed":"Optional")+'</span>':'<button class="favorite" data-favorite="'+id+'" aria-label="Favorite '+name+'" aria-pressed="'+favorite+'">'+(favorite?"★":"☆")+'</button>')+'</div><h3>'+name+'</h3><small>'+upstream+'</small><p>'+desc+'</p><button class="tile-action" data-'+(catalog?"app":"open")+'="'+id+'">'+(catalog?"View details": "Open preview")+' <span aria-hidden="true">›</span></button></article>';}
function tileGrid(items,catalog=false){return '<div class="grid '+(catalog?"catalog-grid":"resource-grid")+'">'+(items.length?items.map(t=>tile(t,catalog)).join(""):'<p>No matching tools.</p>')+'</div>';}
function metric(label,value,note){return '<article class="metric"><small>'+label+'</small><strong>'+value+'</strong><small>'+note+'</small></article>';}
function list(items){return '<ul class="list">'+items.map(([a,b])=>'<li><span>'+a+'</span><span class="status">'+b+'</span></li>').join("")+'</ul>';}
function panel(title,body){return '<section class="panel stack"><h2>'+title+'</h2>'+body+'</section>';}
const notices=[
  {id:1,title:"Example archive indexed",detail:"Review local knowledge availability; physical offline reading is not verified.",kind:"Information",target:"content",read:false},
  {id:2,title:"Example restore verification pending",detail:"A snapshot does not establish recoverability. Review verification separately.",kind:"Needs attention",target:"backup",read:false},
  {id:3,title:"Example optional application needs setup",detail:"Native account and LAN access are separate from container installation.",kind:"Needs attention",target:"applications",read:false}
];
let noticeId=3, noticeFilter="all";
function recordActivity(title,target="activity"){
  activity.unshift(title);
  notices.unshift({id:++noticeId,title,detail:"A prototype action was confirmed. No real service operation was performed.",kind:"Information",target,read:false});
  if(notices.length>50)notices.pop();
  updateNoticeCount();
}
function updateNoticeCount(){const b=$("notifications-shortcut");if(!b)return;b.hidden=workspace!=="admin";const count=notices.filter(n=>!n.read).length;b.textContent="Notifications"+(count?" ("+count+")":"");}
function connectivityPanel(){return panel("Connection & availability",'<p>Separate local access, internet reachability and offline readiness. This design lab cannot measure the appliance or WAN.</p>'+list([["Local preview","Open"],["Appliance LAN access","Not measured"],["Internet reachability","Not measured"],["Physical offline use","Not verified"]])+'<small>In production, a local portal can remain available when internet access is unavailable. Do not infer offline readiness from an installed service.</small>');}
function notificationCards(){
  const visible=notices.filter(n=>noticeFilter==="all"||noticeFilter==="unread"&&!n.read||noticeFilter==="attention"&&n.kind==="Needs attention");
  return visible.length?visible.map(n=>'<article class="panel notice-card"><div class="panel-header"><strong>'+esc(n.title)+'</strong><span class="notice-kind">'+esc(n.kind)+'</span></div><p>'+esc(n.detail)+'</p><small>'+(n.read?"Read":"Unread")+' · Simulated event</small><div class="actions"><button class="quiet" data-page="'+n.target+'">Review related page</button><button class="quiet" data-notice="'+n.id+'">'+(n.read?"Mark unread":"Mark read")+'</button></div></article>').join(""):'<p>No example notifications match this filter. Try all notifications.</p>';
}
function notifications(){return heading("Notifications","Review example events and next steps. This is not a live job or alert feed.")+panel("Example event inbox",'<div class="actions"><div class="field"><label for="notice-filter">Show</label><select id="notice-filter">'+[["all","All notifications"],["unread","Unread"],["attention","Needs attention"]].map(([v,label])=>'<option value="'+v+'" '+(noticeFilter===v?"selected":"")+'>'+label+'</option>').join("")+'</select></div><button id="notice-read-all" class="quiet">Mark all read</button></div><p id="notice-count" role="status">'+notices.filter(n=>!n.read).length+' unread example events</p><div class="stack" id="notice-results">'+notificationCards()+'</div>');}
function refreshNotices(focusId){$("notice-results").innerHTML=notificationCards();$("notice-count").textContent=notices.filter(n=>!n.read).length+" unread example events";updateNoticeCount();if(focusId){const el=document.querySelector('[data-notice="'+focusId+'"]');if(el)el.focus();else $("notice-filter").focus();}}
function overview(){
const shortcuts=[["applications","Applications"],["content","Content & maps"],["supplies","Inventory"],["backup","Recovery"],["updates","Updates"],["notifications","Alerts"]];
return '<div class="operations-title"><div class="eyebrow">Local resource system / design preview</div><h1>Life beyond the grid.</h1><p>Operations overview · example data only</p></div><section class="connection-strip"><h2>Connection & availability</h2><div class="connection-items"><div><small>Local preview</small><strong>Open</strong></div><div><small>Appliance LAN access</small><strong>Not measured</strong></div><div><small>Internet reachability</small><strong>Not measured</strong></div></div></section><div class="grid metrics operations-metrics">'+metric("Applications",installed.size+" installed","Example catalog state")+metric("Offline content","124 GB","Example archive size")+metric("Storage used","42%","Example capacity")+metric("Recovery","Pending","Not verified")+'</div><div class="section-heading"><h2>Quick access</h2></div><div class="quick-grid">'+shortcuts.map(([id,label])=>'<button class="quiet quick-link" data-page="'+id+'">'+icon(id)+'<span>'+label+'</span></button>').join("")+'</div><div class="split">'+panel("Readiness indicators",'<p>Illustrative presence indicators; not a readiness certification.</p>'+list([["Knowledge archives","Example indexed"],["Regional maps","Example present"],["PACE plans","Example saved"],["Physical offline test","Not performed"]]))+panel("Recent activity",list(activity.slice(0,4).map(x=>[x,"Demo"])))+'</div>';
}
function home(){const available=tools.filter(t=>resourceAvailable(t[0]));return '<section class="hero"><div class="eyebrow">Your local resources</div><h1>Life beyond the grid.</h1><p>Find the tools and information available to your household.</p></section><div class="filterbar"><input id="tool-search" aria-label="Search tools" placeholder="Find a tool..." type="search"></div><div id="tool-results">'+tileGrid(available.sort((a,b)=>Number(prefs.favorites.includes(b[0]))-Number(prefs.favorites.includes(a[0]))))+'</div>';}
function catalog(){return heading("Applications","Discover and manage optional services. Nothing is installed from this prototype.")+'<div class="filterbar"><input id="tool-search" type="search" aria-label="Search catalog" placeholder="Search applications"><select id="catalog-filter" aria-label="Filter catalog"><option value="">All applications</option><option value="installed">Installed</option><option value="optional">Optional</option></select><select id="category-filter" aria-label="Filter category"><option value="">All categories</option>'+[...new Set(Object.values(categories))].map(c=>'<option>'+c+'</option>').join("")+'</select></div><div id="tool-results">'+tileGrid(catalogApps,true)+'</div>';}
function demoButton(action,label){return '<button class="quiet" data-demo="'+action+'">'+label+'</button>';}
function table(headers,rows){return '<div class="table-scroll" tabindex="0" role="region" aria-label="'+esc(headers.join(", "))+'"><table><thead><tr>'+headers.map(h=>'<th scope="col">'+esc(h)+'</th>').join("")+'</tr></thead><tbody>'+rows.map(row=>'<tr>'+row.map(v=>'<td>'+esc(v)+'</td>').join("")+'</tr>').join("")+'</tbody></table></div>';}
function appDetails(id){const t=catalogApps.find(x=>x[0]===id);const has=installed.has(id);const state=appStates[id]||"Example running";return heading(t[1],t[3])+ '<div class="grid metrics">'+metric("Install state",has?"Installed":"Optional","Simulated catalog")+metric("Service state",has?state:"Not installed","No live probe")+metric("Native access","Unverified","Separate native permissions")+'</div><div class="split">'+panel("Application management",'<p>Lifecycle preview. Removal retains application data in the real system unless a separate destructive action is confirmed.</p><div class="actions">'+(has?demoButton("start:"+id,"Start")+demoButton("stop:"+id,"Stop")+demoButton("restart:"+id,"Restart"):"")+(has?"":'<button data-install-demo="'+id+'">Simulate installation</button>')+'</div>'+list([["Native application",t[2]],["Image identity","Not checked"],["Storage requirement","Not estimated"]]))+panel("Native access & configuration",'<p>Keep native authentication, verify initial setup and explicitly approve trusted-LAN sharing.</p>'+list([["Account setup","Not verified"],["LAN sharing","Not verified"],["HTTP transport","Unencrypted unless configured"]])+'<div class="actions">'+demoButton("native:"+id,"Preview native setup")+demoButton("share:"+id,"Preview LAN sharing")+'</div>')+'</div><div class="split">'+panel("Updates",list([["Reviewed version","Example pinned release"],["Registry check","Not performed"],["Rollback","Requires compatible data"]])+demoButton("update:"+id,"Preview update"))+panel("Backup & recovery",list([["Coverage","Not verified"],["Snapshot","Example only"],["Restore check","Not performed"]])+ '<div class="actions">'+demoButton("snapshot:"+id,"Preview snapshot")+demoButton("verify:"+id,"Preview verification")+'</div>')+'</div>'+(has?panel("Removal",'<p>Remove only the example service. No live containers or data are changed. Production removal must preserve data by default.</p><button class="quiet" data-install-demo="'+id+'">Simulate removal</button>'):"")+'<details class="panel"><summary>Advanced diagnostics</summary><p>No logs or real container identifiers are present in this preview.</p></details><button class="quiet" data-page="applications">Back to catalog</button>';}

function filterTiles(){const q=$("tool-search").value.toLowerCase(),isCatalog=page==="applications",status=$("catalog-filter")?.value||"",category=$("category-filter")?.value||"";let items=(isCatalog?catalogApps:tools.filter(t=>resourceAvailable(t[0]))).filter(t=>t.join(" ").toLowerCase().includes(q)&&(!category||categories[t[0]]===category)&&(!status||(status==="installed"?installed.has(t[0]):!installed.has(t[0]))));if(!isCatalog)items.sort((a,b)=>Number(prefs.favorites.includes(b[0]))-Number(prefs.favorites.includes(a[0])));$("tool-results").innerHTML=tileGrid(items,isCatalog);}
function appearance(){const theme=themeResolve().theme;return heading("Appearance","Choose your theme and layout. Preferences stay in this browser.")+panel("Theme",'<div class="theme-options">'+themeList().map(t=>'<button class="theme-choice quiet" data-theme-choice="'+t.id+'" aria-pressed="'+(t.id===theme.id)+'"><span class="swatches">'+[t.dark.bg,t.dark.panel,t.dark.accent,t.light.bg].map(c=>'<span style="background:'+c+'"></span>').join("")+'</span><strong>'+esc(t.name)+'</strong><small>'+esc(t.description)+'</small></button>').join("")+'</div>')+panel("Display preferences",'<div class="field"><label for="mode">Color mode</label><select id="mode"><option value="system">Follow system</option><option value="light">Light</option><option value="dark">Dark</option></select></div><div class="field"><label for="density">Density</label><select id="density"><option value="comfortable">Comfortable</option><option value="compact">Compact</option></select></div><label class="check"><input type="checkbox" id="motion"> Reduce motion</label><div class="actions"><button class="quiet" id="reset">Reset appearance</button></div><p>Preferences apply only to this design preview.</p>')+themePackagePanel()+'<details class="panel" id="studio-details"><summary>Advanced · Theme Studio</summary><section class="stack" id="studio"></section></details>';}
function themePackagePanel(){const custom=customPackages.find(p=>p.theme.id===prefs.theme);const current=custom||T.builtinPackages.find(p=>p.theme.id===prefs.theme)||T.builtinPackages[0];return panel("Local theme packages",'<p>Import validated v1 JSON from this device. Local packages are unreviewed and stay in this browser. No scripts, CSS or remote assets are supported.</p><div class="field"><label for="theme-file">Choose JSON theme</label><input type="file" id="theme-file" accept=".json,application/json"></div><div class="field"><label for="theme-json">Or paste a theme manifest</label><textarea id="theme-json" rows="6" maxlength="16384" placeholder="Paste a theme JSON package"></textarea></div><div class="actions"><button id="theme-import">Import pasted theme</button><button id="theme-example" class="quiet">Load example</button><button id="theme-export" class="quiet">Export selected JSON</button><button id="theme-download" class="quiet">Download JSON</button>'+(custom?'<button id="theme-remove" class="quiet">Remove selected local theme</button>':'')+'</div><p id="theme-result" role="status" aria-live="polite"></p><small>Selected package: '+esc(current.theme.name)+' · '+esc(current.version)+' · '+(custom?"Local / unreviewed":"Built-in")+'</small>');}
function themeMessage(message){const el=$("theme-result");if(el)el.textContent=message;}
function importTheme(raw){try{const p=T.parsePackage(raw);savePackages(T.addPackage(customPackages,p));prefs.theme=p.theme.id;apply();render();themeMessage("Imported "+p.theme.name+" as a local theme.");$("theme-import").focus();}catch(e){themeMessage(e.message||"Unable to save theme.");}}
function themeExample(){const t={...T.builtins[0],id:"local.expedition",name:"Expedition",description:"Example local theme",radius:10};return JSON.stringify(T.packageOf(t,{author:"Example contributor",license:"MIT"}),null,2);}
function mapPreview(large=false){return '<div class="map-demo '+(large?"map-large":"")+'"><svg viewBox="0 0 600 320" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><g fill="none" stroke="currentColor" opacity=".19">'+Array.from({length:16},(_,i)=>'<path d="M-40 '+(i*25)+' Q160 '+(i*25-80)+' 300 '+(i*25+8)+' T640 '+(i*25-30)+'"/>').join("")+'</g><g fill="none" stroke="currentColor" opacity=".32"><path d="M-20 245 Q180 220 280 245 T640 180" stroke-width="8"/><path d="M180 -20 Q240 110 280 245 T400 350" stroke-width="5"/></g><path d="M80 235 150 195 270 213 330 130 495 103" stroke="currentColor" stroke-width="4" fill="none" stroke-dasharray="8 5"/><g fill="currentColor"><circle cx="80" cy="235" r="7"/><circle cx="495" cy="103" r="7"/><text x="93" y="255" font-size="13">A</text><text x="508" y="103" font-size="13">B</text></g></svg><div class="map-label">SCHEMATIC PREVIEW</div><span class="map-caption">Illustrative path only · not navigation data</span></div>';}
function mapWorkspace(){
  return '<div class="map-workspace"><section class="map-main stack"><div class="panel-header"><h2>Map workspace</h2><span class="status">Example only</span></div>'+mapPreview(true)+'<div class="map-legend"><span>A · Example start</span><span>B · Example destination</span></div><p>No actual map tiles, position or route computation are connected to this preview.</p></section>'+panel("Route planner",'<div class="field"><label for="route-start">Example start</label><input id="route-start" value="Home"></div><div class="field"><label for="route-end">Example destination</label><input id="route-end" value="Meeting point"></div><div class="actions"><button class="quiet" id="route-swap" type="button">Swap endpoints</button></div><div class="field"><label for="route-mode">Travel mode</label><select id="route-mode"><option>Driving</option><option>Walking</option><option>Cycling</option></select></div>'+demoButton("route","Preview route request")+'<small>Route distance and travel time are not available.</small>')+'</div>'+panel("Saved locations",table(["Name","Type","Availability"],[["Home","Example waypoint","Not verified"],["Meeting point","Example waypoint","Not verified"]]))+panel("Offline map status",list([["Local basemap","Not connected"],["Routing graph","Not verified"],["Physical disconnected use","Not tested"]]));
}
function paceWorkspace(){
  const stages=[["P","Primary","Local mesh","Routine first choice."],["A","Alternate","Handheld radio","Alternate if the first method is unavailable."],["C","Contingency","Phone","An additional method if usable."],["E","Emergency","Agreed meeting point","Previously agreed family plan."]];
  return panel("PACE plan",'<p>Example family communications plan. No method has been tested in this preview.</p><div class="pace-grid">'+stages.map(([letter,label,method,description])=>'<article class="pace-card"><div class="pace-top"><span class="pace-letter" aria-hidden="true">'+letter+'</span><span class="pace-stage">'+label+'</span><span class="pace-status">Not tested</span></div><h3>'+method+'</h3><p>'+description+'</p></article>').join("")+'</div>'+demoButton("pace","Preview plan editor"))+'<div class="split">'+panel("Communications status",list([["MeshMonitor","Example service"],["Meshtastic","Radio not connected"],["MeshCore","Radio not connected"],["Last check","Manual record only"]]))+panel("Device directory",table(["Device","Method","Check"],[["Household radio","Meshtastic","Not recorded"],["Spare handset","MeshCore","Not recorded"]])+demoButton("device","Preview manual check"))+'</div>';
}
function resource(id){const t=tools.find(x=>x[0]===id);const title=t?.[1]||"Resource";const desc=t?.[3]||"Illustrative resource page.";let body="";
if(id==="maps")body=mapWorkspace();
else if(id==="communications"||id==="plans")body=paceWorkspace();
else if(id==="supplies")body=panel("Household resources",table(["Resource","Native tool","Access"],[["Food and recipes","Grocy","Native login"],["Durable equipment","Homebox","Native login"]])+'<p>No private stock counts are displayed in this household preview.</p>');
else body=panel("Local resources",list([[t?.[2]||"AfterGrid","Example resource"],["Content","Not verified"],["Native access","Not connected"]])+demoButton("open-resource","Preview native application"));
return heading(title,desc)+body+'<div class="actions"><button class="quiet" data-page="home">Back to dashboard</button></div>';}

function sectionPage(id){if(id==="content")return heading("Content & maps","Manage downloaded knowledge and regional map datasets.")+'<div class="grid metrics">'+metric("Archives","3 example","Not checked")+metric("Storage","124 GB","Illustrative")+metric("Downloads","0 active","Simulated")+'</div>'+panel("Knowledge library",'<div class="field"><label for="content-topic">Catalog search preview</label><input id="content-topic" placeholder="Search official archive catalog"></div>'+demoButton("catalog-search","Preview catalog search")+table(["Archive","Language","Status"],[["Reference collection","English","Example indexed"],["Gardening guide","English","Example local"],["Education collection","English","Example available"]]))+panel("Regional maps",mapPreview()+'<div class="field"><label for="region">Example region</label><select id="region"><option>South Carolina</option><option>North Carolina</option><option>Georgia</option></select></div><div class="actions">'+demoButton("estimate","Preview size estimate")+demoButton("download","Preview download")+'</div><p>Real downloads need explicit storage estimates, upstream integrity checks and confirmation.</p>')+panel("Routing dataset",list([["Local graph","Not verified"],["Replacement slot","Not prepared"]])+demoButton("routing","Preview graph preparation"));
if(id==="supplies")return heading("Households & inventory","Keep ownership distinct from physical storage.")+panel("Household directory",table(["Household","Mapped location","Native app"],[["Main household","Pantry","Grocy"],["Second household","Workshop","Homebox"]])+demoButton("household","Preview household editor"))+panel("Inventory report",'<div class="grid"><div class="field"><label for="household-filter">Household</label><select id="household-filter"><option>All households</option><option>Main household</option><option>Second household</option></select></div><div class="field"><label for="group-by">Group by</label><select id="group-by"><option>Ownership</option><option>Physical storage</option></select></div></div><p>Private report layout only. No credentials or native quantities are present. An unavailable location is not empty.</p>'+demoButton("inventory","Preview report request"))+panel("Native connections",list([["Homebox","Not connected"],["Grocy","Not connected"]])+demoButton("inventory-connect","Preview API connection"));
if(id==="updates")return heading("Updates","Reviewed releases, explicit approvals and independent application maintenance.")+panel("AfterGrid core",list([["Current version","Example development release"],["Candidate","Not checked"],["Production activation","Not connected"],["Independent apps","Must remain available"]])+demoButton("core-update","Preview reviewed update"))+panel("Application updates",table(["Application","Installed image","Reviewed candidate"],[["Kiwix","Example pinned","Not checked"],["Grocy","Example pinned","Not checked"],["Homebox","Example pinned","Not checked"]])+'<div class="actions">'+demoButton("registry","Preview registry check")+demoButton("app-update","Preview application update")+'</div><p>No automatic updates enabled. Actual update admission requires verified recovery evidence and reviewed compatibility.</p>');
if(id==="backup")return heading("Backup & recovery","Separate backup presence from actual restore verification.")+'<div class="grid metrics">'+metric("Repository","Example","Not connected")+metric("Coverage","Not checked","No live data")+metric("Restore","Not verified","No restore run")+'</div>'+panel("Backup coverage",table(["Source","Snapshot","Verification"],[["Core configuration","Example captured","Not verified"],["Worker state","Example captured","Not verified"],["Native app data","Not checked","Not verified"],["Offline content","Not checked","Not verified"]])+'<div class="actions">'+demoButton("snapshot","Preview snapshot")+demoButton("verify","Preview restore check")+'</div>')+panel("Backup schedules",list([["Schedule","Disabled in preview"],["Retention","Native Kopia policy required"]])+demoButton("schedule","Preview schedule"))+panel("Portable recovery",'<p>Inventory alone is not a complete recovery package. Actual recovery must validate exact versions, images, data, credentials and an independent clean-machine startup.</p><div class="actions">'+demoButton("recovery-inventory","Preview inventory")+demoButton("recovery-package","Preview package preparation")+'</div>');
return heading("Activity","Persistent job and operation history layout.")+panel("Example activity",table(["Operation","State"],activity.map(x=>[x,"Demo"])))}

function wizard(){const stages=["Welcome","Choose applications","Review selection","Installation","Ready"];let body="";if(step===0)body='<p>Welcome to the AfterGrid setup preview. In the real portal, a local administrator is created before optional applications are selected. No credentials are collected here.</p>';if(step===1)body='<p>Nothing is selected by default. You can skip all optional applications.</p>'+catalogApps.map(t=>'<label class="check"><input type="checkbox" data-select="'+t[0]+'" '+(selected.has(t[0])?"checked":"")+'>'+t[1]+'</label>').join("");if(step===2)body='<p>Review your example selection. No real storage or dependency checks have been run.</p>'+list(selected.size?[...selected].map(id=>[catalogApps.find(t=>t[0]===id)[1],"Selected"]):[["Core only","No optional apps"]]);if(step===3)body='<p>Simulated installation summary — no containers are downloaded or started.</p>'+list(selected.size?[...selected].map(id=>[catalogApps.find(t=>t[0]===id)[1],"Example complete"]):[["Core","Example ready"]]);if(step===4)body='<p>Your design preview is ready. The real setup must retain native account setup, explicit sharing and actual readiness checks.</p>';return heading("First-run setup","Interactive five-stage design preview.")+'<div class="stepbar" aria-label="Step '+(step+1)+' of 5">'+stages.map((s,i)=>'<span class="'+(i<=step?"done":"")+'"></span>').join("")+'</div>'+panel((step+1)+". "+stages[step],body+'<div class="actions">'+(step>0?'<button class="quiet" data-step="back">Back</button>':'')+(step<4?'<button data-step="next">'+(step===2?"Simulate installation":"Continue")+'</button>':'<button data-page="overview">Open dashboard</button>')+(step===1?'<button class="quiet" data-step="skip">Skip optional apps</button>':'')+'</div>');}
const marketItems=[{id:"expedition",name:"Expedition",type:"Themes",publisher:"Example contributor",version:"1.0.0",description:"Natural colors and topographic styling.",details:"Declarative theme tokens only; no scripts or remote assets."},{id:"nightfall",name:"Nightfall",type:"Themes",publisher:"Example contributor",version:"1.0.0",description:"High-contrast charcoal and blue.",details:"Would require the v1 theme contract and local validation."},{id:"homestead",name:"Homestead Library",type:"Content",publisher:"Example contributor",version:"1.0.0",description:"Gardening and food preservation references.",details:"Would require reviewed sources, distribution rights and verified file checksums."},{id:"regional",name:"Regional Map Pack",type:"Content",publisher:"Example contributor",version:"1.0.0",description:"Regional offline basemap and routing data.",details:"Would require separate map and routing compatibility and storage estimates."},{id:"weather",name:"Weather Station",type:"Modules",publisher:"Example contributor",version:"1.0.0",description:"Local environmental monitoring.",details:"Would require reviewed pinned images, native configuration, host permission and backup review."},{id:"home-auto",name:"Home Automation",type:"Modules",publisher:"Example contributor",version:"1.0.0",description:"Local home automation integration.",details:"Would require reviewed Compose definitions and restricted worker admission."}];
let marketSelected=null,marketCategory="",marketQuery="",marketRefresh=false;
function marketCards(){const items=marketItems.filter(p=>(!marketCategory||p.type===marketCategory)&&(p.name+" "+p.description).toLowerCase().includes(marketQuery.toLowerCase()));return '<div class="grid">'+(items.length?items.map(p=>'<article class="tile"><div class="tile-top"><div class="tile-icon">'+icon(p.type==="Themes"?"appearance":p.type==="Content"?"knowledge":"applications")+'</div><small>'+p.type+'</small></div><h3>'+p.name+'</h3><small>'+p.publisher+' · '+p.version+'</small><p>'+p.description+'</p><button class="tile-action" data-market="'+p.id+'">View example package <span aria-hidden="true">›</span></button></article>').join(""):'<p>No matching example packages.</p>')+'</div>';}
function marketplace(){const p=marketItems.find(x=>x.id===marketSelected);return heading("Marketplace","Future curated community themes, content and modules.")+panel("Catalog status",'<p>Hypothetical catalog only. No repository, signatures, real package download or installation exists in this preview.</p>'+list([["Catalog","Example cached listings"],["Verification","Not performed"],["Automatic refresh","Disabled"],["Last refresh",marketRefresh?"Example refresh requested":"Not performed"]])+demoButton("market-refresh","Preview catalog refresh"))+(p?panel(p.name,'<p>'+p.description+'</p>'+list([["Package type",p.type],["Publisher",p.publisher],["Version",p.version],["Trust","Illustrative, unreviewed"],["Compatibility","Not validated"],["License","Not established"],["Download size","Not measured"]])+'<p>'+p.details+'</p><div class="actions">'+demoButton("market-install","Preview install approval")+'<button class="quiet" id="market-back">Back to listings</button></div>'):'<div class="filterbar"><input id="market-search" type="search" aria-label="Search marketplace" placeholder="Search example packages" value="'+esc(marketQuery)+'"><select id="market-category" aria-label="Marketplace category"><option value="">All categories</option>'+["Themes","Content","Modules"].map(v=>'<option '+(marketCategory===v?"selected":"")+'>'+v+'</option>').join("")+'</select></div><div id="market-results">'+marketCards()+'</div>');}
function render(){nav();$("page").innerHTML=page==="overview"?overview():page==="home"?home():page==="applications"?catalog():page.startsWith("app-")?appDetails(page.slice(4)):page==="appearance"?appearance():page==="setup"?wizard():page==="marketplace"?marketplace():page==="notifications"?notifications():workspace==="admin"&&["content","supplies","updates","backup","activity"].includes(page)?sectionPage(page):resource(page);if(page==="appearance"){$("mode").value=prefs.mode;$("density").value=prefs.density;$("motion").checked=prefs.motion;AfterGridStudio.mount($("studio"),themeResolve().theme,raw=>{const p=T.parsePackage(raw);savePackages(T.addPackage(customPackages,p));prefs.theme=p.theme.id;apply();render();themeMessage("Created "+p.theme.name+" as a local theme.");document.querySelector('[data-theme-choice="'+p.theme.id+'"]').focus();});}document.title="AfterGrid | "+(document.querySelector("#page h1")?.textContent||"Design preview");}
let dialogAction=null,returnFocus=null;
function confirmDemo(title,desc,callback){returnFocus=document.activeElement;dialogAction=callback;$("dialog-title").textContent=title;$("dialog-description").textContent=desc;$("confirmation").showModal();}
$("dialog-cancel").addEventListener("click",()=>$("confirmation").close("cancel"));
$("dialog-confirm").addEventListener("click",()=>$("confirmation").close("confirm"));
$("confirmation").addEventListener("close",()=>{const action=dialogAction;dialogAction=null;if($("confirmation").returnValue==="confirm"&&action)action();if(returnFocus?.isConnected)returnFocus.focus();else $("main").focus();returnFocus=null;});
$("confirmation").addEventListener("cancel",e=>{e.preventDefault();$("confirmation").close("cancel");});
$("workspace").addEventListener("change",e=>{setMenu(false);workspace=e.target.value;go(workspace==="home"?"home":"overview");});
function setMenu(open,returnFocus=false){
  document.querySelector(".shell").classList.toggle("menu-open",open);
  $("menu").setAttribute("aria-expanded",String(open));
  if(open)$("workspace").focus();
  else if(returnFocus)$("menu").focus();
}
$("menu").addEventListener("click",()=>setMenu(!document.querySelector(".shell").classList.contains("menu-open"),true));
$("workspace-sidebar").addEventListener("keydown",e=>{if(e.key==="Escape"&&document.querySelector(".shell").classList.contains("menu-open")&&$("menu").getClientRects().length){e.preventDefault();setMenu(false,true);}});
matchMedia("(max-width: 850px)").addEventListener("change",e=>{if(!e.matches)setMenu(false);});

$("navigation").addEventListener("click",e=>{if(e.target.closest("a")){setMenu(false);$("main").focus();}});
$("appearance-shortcut").addEventListener("click",()=>go("appearance"));
$("notifications-shortcut").addEventListener("click",()=>go("notifications"));
$("page").addEventListener("input",e=>{if(e.target.id==="tool-search")filterTiles();else if(e.target.id==="market-search"){marketQuery=e.target.value;$("market-results").innerHTML=marketCards();}});
$("page").addEventListener("change",e=>{const t=e.target;if(t.id==="theme-file"){const file=t.files?.[0];if(file){if(file.size>T.MAX_BYTES){themeMessage("File exceeds 16 KiB.");return;}file.text().then(raw=>{if(page==="appearance")importTheme(raw);}).catch(()=>themeMessage("Unable to read file."));}}else if(t.id==="market-category"){marketCategory=t.value;$("market-results").innerHTML=marketCards();}else if(t.id==="notice-filter"){noticeFilter=t.value;refreshNotices();}else if(t.id==="catalog-filter"||t.id==="category-filter")filterTiles();else if(t.id==="mode"){prefs.mode=t.value;apply();}else if(t.id==="density"){prefs.density=t.value;apply();}else if(t.id==="motion"){prefs.motion=t.checked;apply();}else if(t.dataset.select){if(t.checked)selected.add(t.dataset.select);else selected.delete(t.dataset.select);}});
$("page").addEventListener("click",e=>{const b=e.target.closest("button");if(!b)return;const d=b.dataset;if(b.id==="route-swap"){const a=$("route-start"),z=$("route-end");[a.value,z.value]=[z.value,a.value];}else if(d.page){go(d.page);}else if(d.notice){const n=notices.find(x=>x.id===Number(d.notice));if(n){n.read=!n.read;refreshNotices(n.id);}}else if(b.id==="notice-read-all"){for(const n of notices)n.read=true;refreshNotices();}else if(d.themeChoice){prefs.theme=d.themeChoice;apply();render();document.querySelector('[data-theme-choice="'+prefs.theme+'"]').focus();}else if(d.favorite){const id=d.favorite;prefs.favorites=prefs.favorites.includes(id)?prefs.favorites.filter(x=>x!==id):[...prefs.favorites,id];persist();filterTiles();document.querySelector('[data-favorite="'+id+'"]')?.focus();}else if(d.open){go(d.open);}else if(d.app){go("app-"+d.app);}else if(d.installDemo){const t=catalogApps.find(x=>x[0]===d.installDemo);if(!t)return;const has=installed.has(t[0]);confirmDemo(t[1],(has?"Simulate removing the application from the example catalog.":"Simulate adding the application to the example catalog.")+" No real services or data will change.",()=>{if(has){installed.delete(t[0]);delete appStates[t[0]];}else{installed.add(t[0]);appStates[t[0]]="Example running";}recordActivity("Example: "+t[1]+(has?" removed":" installed"),"applications");render();});}else if(d.market){marketSelected=d.market;render();$("main").focus();}else if(b.id==="market-back"){marketSelected=null;render();$("main").focus();}else if(d.demo){confirmDemo("Preview "+d.demo+" operation","This demonstrates a confirmation dialog only. No requests, snapshots, downloads or updates will be executed.",()=>{const [action,id]=d.demo.split(":");if(id&&["start","stop","restart"].includes(action)&&installed.has(id)){appStates[id]=action==="stop"?"Example stopped":"Example running";render();}recordActivity("Example: "+d.demo+" confirmation",workspace==="admin"?page:"activity");if(d.demo==="market-refresh"){marketRefresh=true;render();}});}else if(d.step){if(d.step==="skip"){selected.clear();step=2;}else if(d.step==="next")step=Math.min(4,step+1);else step=Math.max(0,step-1);render();$("main").focus();}else if(b.id==="theme-import"){importTheme($("theme-json").value);}else if(b.id==="theme-example"){$("theme-json").value=themeExample();$("theme-json").focus();}else if(b.id==="theme-export"||b.id==="theme-download"){const p=customPackages.find(p=>p.theme.id===prefs.theme)||T.builtinPackages.find(p=>p.theme.id===prefs.theme)||T.builtinPackages[0];const exported=customPackages.includes(p)?p:T.packageOf({...p.theme,id:"local."+p.theme.id+"-copy",name:p.theme.name+" copy"},{author:p.author,license:p.license});$("theme-json").value=JSON.stringify(exported,null,2);$("theme-json").focus();$("theme-json").select();if(b.id==="theme-download"){const url=URL.createObjectURL(new Blob([$("theme-json").value+"\n"],{type:"application/json"}));const a=document.createElement("a");a.href=url;a.download=exported.theme.id+".json";document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}themeMessage("Export ready. Copy the JSON into a local .json file to share or select Download JSON.");}else if(b.id==="theme-remove"){const id=prefs.theme;confirmDemo("Remove local theme","Only the local browser copy will be removed. AfterGrid will return to its built-in theme.",()=>{try{savePackages(customPackages.filter(p=>p.theme.id!==id));prefs.theme=defaultPrefs.theme;apply();render();themeMessage("Local theme removed.");}catch(e){themeMessage("Unable to remove local theme.");}});}else if(b.id==="reset"){prefs={...defaultPrefs,favorites:prefs.favorites};apply();render();$("reset").focus();}});
system.addEventListener("change",()=>{if(prefs.mode==="system")apply();});
window.addEventListener("hashchange",()=>{readRoute();$("main").focus();});
apply();readRoute();
